-- SQLite Database Schema for Ensemble Forecasting System
-- Auto-generated by database_init.py

PRAGMA foreign_keys = ON;

CREATE TABLE datasets (
	id INTEGER NOT NULL, 
	dataset_name VARCHAR(100) NOT NULL, 
	source_url TEXT, 
	description TEXT, 
	total_records INTEGER, 
	total_features INTEGER, 
	target_column VARCHAR(50), 
	file_path TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE model_runs (
	id INTEGER NOT NULL, 
	experiment_name VARCHAR(100), 
	model_name VARCHAR(100) NOT NULL, 
	algorithm VARCHAR(100), 
	dataset_id INTEGER, 
	training_records INTEGER, 
	validation_records INTEGER, 
	test_records INTEGER, 
	mae FLOAT, 
	mse FLOAT, 
	rmse FLOAT, 
	r2_score FLOAT, 
	mape FLOAT, 
	improvement_percentage FLOAT, 
	hyperparameters TEXT, 
	model_path TEXT, 
	training_started_at DATETIME, 
	training_completed_at DATETIME, 
	status VARCHAR(50) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(dataset_id) REFERENCES datasets (id) ON DELETE CASCADE
);

CREATE TABLE predictions (
	id INTEGER NOT NULL, 
	model_run_id INTEGER NOT NULL, 
	timestamp VARCHAR(50) NOT NULL, 
	actual_value FLOAT NOT NULL, 
	predicted_value FLOAT NOT NULL, 
	prediction_error FLOAT NOT NULL, 
	prediction_type VARCHAR(50) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(model_run_id) REFERENCES model_runs (id) ON DELETE CASCADE
);

CREATE TABLE forecasts (
	id INTEGER NOT NULL, 
	model_run_id INTEGER, 
	forecast_date VARCHAR(50) NOT NULL, 
	forecast_horizon INTEGER NOT NULL, 
	predicted_value FLOAT NOT NULL, 
	lower_prediction_bound FLOAT NOT NULL, 
	upper_prediction_bound FLOAT NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(model_run_id) REFERENCES model_runs (id) ON DELETE CASCADE
);

CREATE TABLE feature_importance (
	id INTEGER NOT NULL, 
	model_run_id INTEGER NOT NULL, 
	feature_name VARCHAR(100) NOT NULL, 
	importance_score FLOAT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(model_run_id) REFERENCES model_runs (id) ON DELETE CASCADE
);

CREATE TABLE cross_validation_results (
	id INTEGER NOT NULL, 
	model_run_id INTEGER NOT NULL, 
	fold_number INTEGER NOT NULL, 
	mae FLOAT NOT NULL, 
	rmse FLOAT NOT NULL, 
	r2_score FLOAT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(model_run_id) REFERENCES model_runs (id) ON DELETE CASCADE
);

CREATE TABLE system_logs (
	id INTEGER NOT NULL, 
	log_level VARCHAR(20) NOT NULL, 
	message TEXT NOT NULL, 
	module_name VARCHAR(100) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);

-- Indexes
CREATE INDEX IF NOT EXISTS idx_predictions_model_run_id ON predictions(model_run_id);
CREATE INDEX IF NOT EXISTS idx_predictions_timestamp ON predictions(timestamp);
CREATE INDEX IF NOT EXISTS idx_forecasts_model_run_id ON forecasts(model_run_id);
CREATE INDEX IF NOT EXISTS idx_forecasts_date ON forecasts(forecast_date);
CREATE INDEX IF NOT EXISTS idx_feature_importance_model_run_id ON feature_importance(model_run_id);
CREATE INDEX IF NOT EXISTS idx_cv_results_model_run_id ON cross_validation_results(model_run_id);
CREATE INDEX IF NOT EXISTS idx_system_logs_created_at ON system_logs(created_at);
